const accountMetrics = $('Fetch Account Metrics').item.json;
const scheduleStats = $('Fetch Schedule Stats').item.json;

const followers = accountMetrics.followers || 0;
const weeklyReach = accountMetrics.weeklyReach || 0;
const weeklyImpressions = accountMetrics.weeklyImpressions || 0;
const posted = scheduleStats.stats?.posted || 0;
const ready = scheduleStats.stats?.ready || 0;

const report = [
  'Weekly Instagram Report - Pawcasso Atelier',
  '=======================================',
  '',
  `Followers: ${followers.toLocaleString()}`,
  `Weekly Reach: ${weeklyReach.toLocaleString()}`,
  `Weekly Impressions: ${weeklyImpressions.toLocaleString()}`,
  '',
  'Posting Schedule:',
  `  Total posted: ${posted}`,
  `  Ready to post: ${ready}`,
  `  Total in queue: ${scheduleStats.stats?.total || 0}`,
  '',
  'Recent Posts:',
  ...(scheduleStats.recentPosts || []).map(p =>
    `  #${p.id} - ${p.postedAt?.split('T')[0]} - ${p.caption?.substring(0, 60)}...`
  ),
  '',
  `Report generated: ${new Date().toISOString().split('T')[0]}`,
].join('\n');

return [{
  json: {
    report,
    followers,
    weeklyReach,
    weeklyImpressions,
    posted,
    ready,
    date: new Date().toISOString().split('T')[0]
  }
}];
